/**
 * Declarative state-machine rules for entity rows — the VALIDATION half of
 * entity write policy, deliberately separate from the permission half.
 *
 * `runMutationGate` answers a PERMISSION question: may this principal write
 * this field. Its request is keyed on `principalKind`, ownership, and approval
 * state. This module answers a VALIDATION question: is the resulting state
 * legal. That question has no principal in it — a posted invoice is immutable
 * whether an agent, an automation, or a human proposed the write — which is
 * exactly why these rules must not live in a principal-keyed pipeline.
 *
 * Pure: no database, no clock, no principal. Entity types opt in by storing
 * `x-transitions` on `entity_types.metadata_schema`; a type declaring nothing
 * is untouched. "Frozen" means no VALUE change, so an idempotent rewrite of an
 * existing value is allowed.
 */

import { isDeepStrictEqual } from "node:util";

/** One declared state and the moves that may leave it. */
interface TransitionState {
	/** States this one may move to. Empty ⇒ terminal. */
	to: string[];
	/** When true, only the state field and `writableOnExit` fields may change. */
	frozen: boolean;
	/** Target state -> fields that may change alongside that transition. */
	writableOnExit: Record<string, string[]>;
}

export interface TransitionSpec {
	field: string;
	states: Record<string, TransitionState>;
}

/** Raised for a spec that is present but unusable; the caller fails closed. */
export class MalformedSpecError extends Error {}

function asRecord(value: unknown): Record<string, unknown> | null {
	return typeof value === "object" && value !== null && !Array.isArray(value)
		? (value as Record<string, unknown>)
		: null;
}

function parseStringArray(value: unknown, where: string): string[] {
	if (value === undefined) return [];
	if (!Array.isArray(value) || value.some((v) => typeof v !== "string")) {
		throw new MalformedSpecError(`${where} must be an array of strings`);
	}
	return value as string[];
}

/**
 * Parse a tenant-authored spec. Throws rather than returning null: a type that
 * declares `x-transitions` has opted in, so a typo must fail loudly instead of
 * silently disabling the invariant it asked for.
 *
 * State names are tenant data used as object keys, so every map here is a
 * null-prototype object and every membership test uses `Object.hasOwn` — a
 * state named `constructor` must not resolve through the prototype chain.
 */
export function parseTransitionSpec(raw: unknown): TransitionSpec {
	const spec = asRecord(raw);
	if (!spec) throw new MalformedSpecError("x-transitions must be an object");

	const field = spec.field;
	if (typeof field !== "string" || field.length === 0) {
		throw new MalformedSpecError(
			"x-transitions.field must be a non-empty string",
		);
	}

	const statesRaw = asRecord(spec.states);
	if (!statesRaw || Object.keys(statesRaw).length === 0) {
		throw new MalformedSpecError(
			"x-transitions.states must be a non-empty object",
		);
	}

	const states = Object.create(null) as Record<string, TransitionState>;
	for (const [name, value] of Object.entries(statesRaw)) {
		const state = asRecord(value);
		if (!state) {
			throw new MalformedSpecError(
				`x-transitions.states.${name} must be an object`,
			);
		}
		const frozen = state.frozen;
		if (frozen !== undefined && typeof frozen !== "boolean") {
			throw new MalformedSpecError(
				`x-transitions.states.${name}.frozen must be a boolean`,
			);
		}
		const writableOnExitRaw = asRecord(
			state.writableOnExit === undefined ? {} : state.writableOnExit,
		);
		if (!writableOnExitRaw) {
			throw new MalformedSpecError(
				`x-transitions.states.${name}.writableOnExit must be an object`,
			);
		}
		const writableOnExit = Object.create(null) as Record<string, string[]>;
		for (const [target, fields] of Object.entries(writableOnExitRaw)) {
			writableOnExit[target] = parseStringArray(
				fields,
				`x-transitions.states.${name}.writableOnExit.${target}`,
			);
		}
		states[name] = {
			to: parseStringArray(state.to, `x-transitions.states.${name}.to`),
			frozen: frozen === true,
			writableOnExit,
		};
	}

	// A `to` naming a state that does not exist can never be satisfied, so it is
	// a typo rather than a rule. Catch it at parse time, not at the write.
	for (const [name, state] of Object.entries(states)) {
		for (const target of state.to) {
			if (!Object.hasOwn(states, target)) {
				throw new MalformedSpecError(
					`x-transitions.states.${name}.to names unknown state "${target}"`,
				);
			}
		}
		for (const target of Object.keys(state.writableOnExit)) {
			if (!state.to.includes(target)) {
				throw new MalformedSpecError(
					`x-transitions.states.${name}.writableOnExit names non-transition target "${target}"`,
				);
			}
		}
	}
	return { field, states };
}

/**
 * Decide one write against a parsed spec.
 *
 * `committed` is the row as it stands; `patch` is the EFFECTIVE change about to
 * be written — not a proposal. Validating the patch rather than a proposal is
 * load-bearing: the permission pass strips approval-held fields and the
 * ownership merge rewrites others, so a rule fed the proposal can accept a
 * combination that never reaches the table (a header/line total pair whose
 * header is held for approval, leaving the line to commit against a stale
 * header). Only the patch is what actually lands.
 *
 * Returns a violation reason, or null for "legal".
 */
export function evaluateTransition(args: {
	spec: TransitionSpec;
	committed: Record<string, unknown>;
	patch: Record<string, unknown>;
}): string | null {
	const { spec, committed, patch } = args;
	const fromRaw = committed[spec.field];
	if (typeof fromRaw !== "string") return null;
	const from = Object.hasOwn(spec.states, fromRaw)
		? spec.states[fromRaw]
		: undefined;
	// An undeclared current state gets no opinion: a spec can only describe the
	// states it names, and failing closed here would freeze every row whose value
	// predates the rule. An undeclared TARGET is still denied below, because it
	// can never appear in a declared `to` list.
	if (!from) return null;

	let movingTo: string | null = null;
	if (Object.hasOwn(patch, spec.field)) {
		const next = patch[spec.field];
		if (typeof next !== "string") {
			return `state field "${spec.field}" must be a string`;
		}
		if (next !== fromRaw) movingTo = next;
	}

	if (movingTo !== null && !from.to.includes(movingTo)) {
		return `illegal transition ${fromRaw} -> ${movingTo}`;
	}

	if (from.frozen) {
		const exempt = new Set<string>([spec.field]);
		if (movingTo !== null) {
			for (const f of from.writableOnExit[movingTo] ?? []) exempt.add(f);
		}
		const illegal = Object.keys(patch).filter(
			(f) =>
				!exempt.has(f) &&
				!isDeepStrictEqual(committed[f] ?? null, patch[f] ?? null),
		);
		if (illegal.length > 0) {
			return `frozen in state "${fromRaw}": cannot write ${illegal.sort().join(", ")}`;
		}
	}
	return null;
}

/** Read a spec off a type's `metadata_schema`. Null ⇒ the type declares none. */
export function specFromMetadataSchema(
	rawSchema: unknown,
): TransitionSpec | null {
	const schema = asRecord(
		typeof rawSchema === "string" ? JSON.parse(rawSchema) : rawSchema,
	);
	const raw = schema?.["x-transitions"];
	if (raw === undefined) return null;
	return parseTransitionSpec(raw);
}

/**
 * The entity-row VALIDATION seam.
 *
 * `patchEntityRows` is the single physical writer for entity rows (the
 * `check-entity-write-funnel` gate proves no raw entity SQL lives outside
 * `entity-management.ts`). It is therefore the only place every write
 * converges, and the only place a state invariant can be enforced without
 * depending on 20-odd callers each remembering to ask.
 *
 * Enforcement is structural rather than conventional: `patchEntityRows` accepts
 * only a {@link ValidatedEntityRowPatch}, which this module alone can mint. A
 * caller that forgets to validate does not slip through — it fails to compile.
 *
 * Two reasons validation lives HERE and not in `runMutationGate`:
 *
 *  1. The gate answers a PERMISSION question (may this principal write this
 *     field) and is keyed on `principalKind` + ownership. Validation answers
 *     "is the resulting state legal", which has no principal in it.
 *  2. The gate runs BEFORE approval-held fields are stripped and before the
 *     ownership merge rewrites the patch. It therefore judges a proposal, not
 *     what commits. This seam sees the effective patch — the exact bytes about
 *     to hit the table — so it cannot be fooled by either transformation.
 */

import type { DbClient } from "../db/client";
import type { EntityRowPatch } from "../utils/entity-management";
import {
	MalformedSpecError,
	evaluateTransition,
	specFromMetadataSchema,
} from "./entity-transition-rules";

declare const validatedBrand: unique symbol;

/**
 * An `EntityRowPatch` that has passed validation (or been explicitly exempted).
 * Only this module can produce one — the brand has no public constructor, so
 * `patchEntityRows` cannot be called with an unchecked patch.
 */
export type ValidatedEntityRowPatch = EntityRowPatch & {
	readonly [validatedBrand]: true;
};

/** Thrown when a patch would produce an illegal state. */
export class EntityRowValidationError extends Error {}

/**
 * Patch columns a transition spec can never govern: platform bookkeeping that
 * no tenant declares in its schema. A patch touching only these skips
 * validation entirely — no spec read, no evaluation — which is what keeps the
 * common write off the validation path.
 *
 * The complement (`metadata`, `name`, `slug`, `parentId`, `content`,
 * `softDelete`) IS governed: freezing a document has to stop a rename and a
 * delete, not merely a metadata edit.
 */
const UNGOVERNED_COLUMNS: ReadonlySet<string> = new Set([
	"currentViewTemplateVersionId",
	"fieldControls",
	"enabledClassifiers",
	"embedding",
	"contentHash",
]);

/** Reserved `$`-names the spec sees for non-metadata columns. */
const RESERVED_COLUMN_NAMES: Readonly<Record<string, string>> = {
	name: "$name",
	slug: "$slug",
	parentId: "$parent_id",
	content: "$content",
	softDelete: "$deleted",
};

function touchesGovernedColumn(patch: EntityRowPatch): boolean {
	return Object.keys(patch).some((k) => !UNGOVERNED_COLUMNS.has(k));
}

/**
 * Flatten a patch into the single namespace a spec reasons about: metadata keys
 * plus reserved `$`-names for columns.
 *
 * `patch.metadata` is the fully merged metadata object, not a delta, so most of
 * its keys are unchanged values. `evaluateTransition` compares against the
 * committed row and ignores no-ops, which is what makes passing the whole
 * object correct rather than a source of false violations.
 */
function flatten(
	patch: EntityRowPatch,
	metadata: Record<string, unknown> | null | undefined,
): Record<string, unknown> {
	const flat: Record<string, unknown> = { ...(metadata ?? {}) };
	for (const [column, reserved] of Object.entries(RESERVED_COLUMN_NAMES)) {
		if (Object.hasOwn(patch, column)) {
			flat[reserved] = patch[column as keyof EntityRowPatch] ?? null;
		}
	}
	return flat;
}

interface CommittedRow {
	id: number;
	metadata: unknown;
	metadata_schema: unknown;
	name: string | null;
	slug: string | null;
	parent_id: string | number | null;
	content: string | null;
	deleted_at: Date | null;
}

function committedState(row: CommittedRow): Record<string, unknown> {
	const metadata = (
		typeof row.metadata === "string"
			? JSON.parse(row.metadata)
			: (row.metadata ?? {})
	) as Record<string, unknown>;
	return {
		...metadata,
		$name: row.name ?? null,
		$slug: row.slug ?? null,
		$parent_id: row.parent_id == null ? null : Number(row.parent_id),
		$content: row.content ?? null,
		$deleted: row.deleted_at != null,
	};
}

/**
 * Validate an effective patch against every target row's declared transition
 * spec, returning the patch branded for {@link patchEntityRows}.
 *
 * Queries only the caller's handle — never `getDb()`. A pooled query from
 * inside an entity write transaction is the #2818 deadlock (every pool session
 * parked `idle in transaction` on the same statement), and it would also read a
 * different snapshot than the one being written.
 *
 * @throws EntityRowValidationError when the patch would produce an illegal
 * state, or when a type declares a spec that cannot be parsed (opting in with a
 * typo must fail closed, not silently disable the invariant).
 */
export async function validateEntityRowPatch(params: {
	tx: DbClient;
	ids: number[];
	patch: EntityRowPatch;
}): Promise<ValidatedEntityRowPatch> {
	const { tx, ids, patch } = params;
	const branded = patch as ValidatedEntityRowPatch;
	if (ids.length === 0) return branded;
	// Fast path: nothing a spec could govern, so no read and no evaluation.
	if (!touchesGovernedColumn(patch)) return branded;

	const rows = await tx<CommittedRow>`
    SELECT e.id, e.metadata, e.name, e.slug, e.parent_id, e.content,
           e.deleted_at, et.metadata_schema
    FROM entities e
    JOIN entity_types et ON et.id = e.entity_type_id
    WHERE e.id = ANY(${ids}::bigint[])
  `;

	for (const row of rows) {
		let spec: ReturnType<typeof specFromMetadataSchema>;
		try {
			spec = specFromMetadataSchema(row.metadata_schema);
		} catch (err) {
			if (err instanceof MalformedSpecError) {
				throw new EntityRowValidationError(
					`entity ${row.id}: invalid x-transitions: ${err.message}`,
				);
			}
			throw err;
		}
		if (!spec) continue;

		const reason = evaluateTransition({
			spec,
			committed: committedState(row),
			patch: flatten(patch, patch.metadata),
		});
		if (reason !== null) {
			throw new EntityRowValidationError(`entity ${row.id}: ${reason}`);
		}
	}
	return branded;
}

/**
 * Mint a validated patch WITHOUT running validation.
 *
 * For platform bookkeeping that legitimately sits outside tenant state rules —
 * eval scaffolding, ACL graph upkeep, merge-ledger transitions. Deliberately
 * named and greppable: an exemption should be visible in review, unlike the
 * implicit bypass that every direct `patchEntityRows` caller enjoyed before
 * this seam existed.
 *
 * @param reason why this write is not subject to state validation.
 */
export function unvalidatedEntityRowPatch(params: {
	patch: EntityRowPatch;
	reason: string;
}): ValidatedEntityRowPatch {
	return params.patch as ValidatedEntityRowPatch;
}

