import { describe, expect, it } from "vitest";
import {
	evaluateTransition,
	parseTransitionSpec,
	specFromMetadataSchema,
} from "../entity-transition-rules";

const INVOICE = parseTransitionSpec({
	field: "status",
	states: {
		draft: { to: ["issued", "cancelled"] },
		issued: {
			to: ["posted", "cancelled"],
			frozen: true,
			writableOnExit: { posted: ["einvoice_uuid"] },
		},
		posted: { to: [], frozen: true },
		cancelled: { to: [], frozen: true },
	},
});

function decide(
	committed: Record<string, unknown>,
	patch: Record<string, unknown>,
): string | null {
	return evaluateTransition({ spec: INVOICE, committed, patch });
}

describe("parseTransitionSpec", () => {
	it("accepts a minimal spec and defaults frozen/writableOnExit", () => {
		const spec = parseTransitionSpec({
			field: "state",
			states: { open: { to: [] } },
		});
		expect(spec.field).toBe("state");
		expect(spec.states.open.frozen).toBe(false);
		expect(spec.states.open.writableOnExit).toEqual({});
	});

	it.each([
		["a non-object", "nope"],
		["a missing field", { states: { a: { to: [] } } }],
		["an empty field", { field: "", states: { a: { to: [] } } }],
		["missing states", { field: "s" }],
		["empty states", { field: "s", states: {} }],
		["a non-object state", { field: "s", states: { a: 1 } }],
		[
			"a non-boolean frozen",
			{ field: "s", states: { a: { to: [], frozen: "y" } } },
		],
		["a non-array to", { field: "s", states: { a: { to: "b" } } }],
		["a non-string in to", { field: "s", states: { a: { to: [2] } } }],
		[
			"a non-object writableOnExit",
			{ field: "s", states: { a: { to: [], writableOnExit: [] } } },
		],
		[
			"a null writableOnExit",
			{ field: "s", states: { a: { to: [], writableOnExit: null } } },
		],
	])("rejects %s", (_label, raw) => {
		expect(() => parseTransitionSpec(raw)).toThrow();
	});

	it("rejects a `to` naming a state that does not exist", () => {
		expect(() =>
			parseTransitionSpec({ field: "s", states: { a: { to: ["ghost"] } } }),
		).toThrow(/unknown state "ghost"/);
	});

	it("rejects writableOnExit for a target that is not an outbound transition", () => {
		expect(() =>
			parseTransitionSpec({
				field: "s",
				states: {
					a: { to: ["b"], writableOnExit: { c: ["receipt"] } },
					b: { to: [] },
					c: { to: [] },
				},
			}),
		).toThrow(/non-transition target "c"/);
	});

	it("does not resolve a tenant state name through the prototype chain", () => {
		// State names are tenant data used as object keys. `constructor` must be an
		// ordinary (absent) state, not Object.prototype.constructor.
		const spec = parseTransitionSpec({
			field: "s",
			states: { real: { to: [] } },
		});
		expect(
			evaluateTransition({
				spec,
				committed: { s: "constructor" },
				patch: { anything: 1 },
			}),
		).toBeNull();
	});
});

describe("evaluateTransition", () => {
	it("allows a declared move", () => {
		expect(decide({ status: "draft" }, { status: "issued" })).toBeNull();
	});

	it("denies an undeclared move", () => {
		expect(decide({ status: "draft" }, { status: "posted" })).toMatch(
			/illegal transition draft -> posted/,
		);
	});

	it("denies any move out of a terminal state", () => {
		expect(decide({ status: "posted" }, { status: "draft" })).toMatch(
			/illegal transition/,
		);
	});

	it("denies editing a non-state field while frozen", () => {
		expect(decide({ status: "posted" }, { grand_total: 1 })).toMatch(
			/frozen in state "posted".*grand_total/,
		);
	});

	it("names every offending field, sorted, so the message is deterministic", () => {
		expect(decide({ status: "posted" }, { b: 1, a: 2 })).toMatch(
			/cannot write a, b$/,
		);
	});

	it("allows a writableOnExit field in the same write as its move", () => {
		expect(
			decide({ status: "issued" }, { status: "posted", einvoice_uuid: "x" }),
		).toBeNull();
	});

	it("scopes writableOnExit to the declared target, not any move", () => {
		expect(
			decide({ status: "issued" }, { status: "cancelled", einvoice_uuid: "x" }),
		).toMatch(/frozen in state "issued".*einvoice_uuid/);
	});

	it("does not grant writableOnExit when the state field is absent", () => {
		expect(decide({ status: "issued" }, { einvoice_uuid: "x" })).toMatch(
			/frozen in state "issued"/,
		);
	});

	it("tolerates a no-op rewrite of an unchanged field while frozen", () => {
		// Load-bearing, not a nicety: `patch.metadata` is the fully MERGED metadata
		// object, so every unchanged key is present on every write. Without deep
		// no-op tolerance a frozen row could never be written at all.
		expect(
			decide(
				{ status: "posted", totals: { net: 100, tax: 20 } },
				{ status: "posted", totals: { tax: 20, net: 100 } },
			),
		).toBeNull();
	});

	it.each([null, 7, undefined])(
		"denies replacing a declared state with non-string %s",
		(value) => {
			expect(decide({ status: "draft" }, { status: value })).toMatch(
				/state field "status" must be a string/,
			);
		},
	);

	it("covers reserved $-attributes, so a frozen entity cannot be renamed", () => {
		expect(decide({ status: "posted" }, { $name: "new" })).toMatch(
			/frozen in state "posted".*\$name/,
		);
	});

	it("abstains when the committed state is not declared", () => {
		// Adoption: adding a spec to a type with existing rows must not freeze every
		// row whose value predates it.
		expect(decide({ status: "legacy" }, { grand_total: 1 })).toBeNull();
	});

	it("abstains when the state field is absent or non-string", () => {
		expect(decide({}, { grand_total: 1 })).toBeNull();
		expect(decide({ status: 7 }, { grand_total: 1 })).toBeNull();
	});

	it("allows unrestricted edits in a non-frozen declared state", () => {
		expect(decide({ status: "draft" }, { grand_total: 1 })).toBeNull();
	});
});

describe("specFromMetadataSchema", () => {
	it("returns null when the type declares no x-transitions", () => {
		expect(specFromMetadataSchema({ type: "object" })).toBeNull();
		expect(specFromMetadataSchema(null)).toBeNull();
	});

	it("parses a schema held as a JSON string", () => {
		const spec = specFromMetadataSchema(
			JSON.stringify({
				"x-transitions": { field: "s", states: { a: { to: [] } } },
			}),
		);
		expect(spec?.field).toBe("s");
	});

	it("throws on a declared but malformed spec (fails closed)", () => {
		expect(() =>
			specFromMetadataSchema({ "x-transitions": { field: "s" } }),
		).toThrow(/states must be a non-empty object/);
	});
});

/**
 * The validation seam at `patchEntityRows`, exercised against real Postgres.
 *
 * The property under test is not "transitions work" but WHERE they are enforced.
 * Validation sits on the physical row writer, so it applies to every caller
 * regardless of principal and regardless of which door the write came through —
 * which is why the human-edit case below passes without touching the
 * `isHumanEdit` carve-out in `updateEntity`.
 */

import { beforeEach, describe, expect, it } from "vitest";
import type { Env } from "../../../index";
import type { ToolContext } from "../../../tools/registry";
import { createEntity, updateEntity } from "../../../utils/entity-management";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	addUserToOrganization,
	createTestAgent,
	createTestOrganization,
	createTestUser,
} from "../../setup/test-fixtures";

const INVOICE_TRANSITIONS = {
	field: "status",
	states: {
		draft: { to: ["issued", "cancelled"] },
		issued: {
			to: ["posted", "cancelled"],
			frozen: true,
			writableOnExit: { posted: ["einvoice_uuid"] },
		},
		posted: { to: [], frozen: true },
		cancelled: { to: [], frozen: true },
	},
};

const TEST_ENV = {} as Env;

async function seedType(
	orgId: string,
	slug: string,
	transitions: unknown,
): Promise<void> {
	const sql = getTestDb();
	await sql`
    INSERT INTO entity_types (organization_id, slug, name, metadata_schema,
                              created_at, updated_at)
    VALUES (${orgId}, ${slug}, ${slug},
            ${sql.json({ type: "object", "x-transitions": transitions })},
            current_timestamp, current_timestamp)
  `;
}

function ctxFor(
	organizationId: string,
	opts: { userId?: string | null; agentId?: string | null },
): ToolContext {
	return {
		organizationId,
		userId: opts.userId ?? null,
		memberRole: "owner",
		agentId: opts.agentId ?? null,
		isAuthenticated: true,
		clientId: null,
		scopes: ["mcp:read", "mcp:write", "mcp:admin"],
		tokenType: "oauth",
		scopedToOrg: true,
		allowCrossOrg: false,
	} as unknown as ToolContext;
}

async function readMetadata(id: number): Promise<Record<string, unknown>> {
	const sql = getTestDb();
	const rows = await sql<{ metadata: unknown }[]>`
    SELECT metadata FROM entities WHERE id = ${id}
  `;
	const raw = rows[0].metadata;
	return (typeof raw === "string" ? JSON.parse(raw) : raw) as Record<
		string,
		unknown
	>;
}

async function seedInvoice(status: string, transitions: unknown = INVOICE_TRANSITIONS) {
	const org = await createTestOrganization({ name: "Row Validation" });
	const user = await createTestUser();
	await addUserToOrganization(user.id, org.id, "owner");
	const agent = await createTestAgent({ organizationId: org.id });
	await seedType(org.id, "invoice", transitions);
	const invoice = await createEntity({
		entity_type: "invoice",
		name: `INV-${status}`,
		organization_id: org.id,
		created_by: user.id,
		metadata: { status, grand_total: 100 },
	} as Parameters<typeof createEntity>[0]);
	return { org, user, agent, invoice };
}

describe("entity row validation at the physical writer", () => {
	beforeEach(async () => {
		await cleanupTestDatabase();
	});

	it("denies an AGENT editing a frozen document", async () => {
		const { org, agent, invoice } = await seedInvoice("posted");

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { grand_total: 999 } },
				TEST_ENV,
				ctxFor(org.id, { agentId: agent.agentId }),
			),
		).rejects.toThrow(/frozen/i);

		expect((await readMetadata(invoice.id)).grand_total).toBe(100);
	});

	/**
	 * The point of moving validation to the row writer. `updateEntity` still wraps
	 * the PERMISSION gate in `if (!isHumanEdit)`, so a human write reaches no
	 * interceptor — yet it is still refused here, because validation is not keyed
	 * on a principal. If this ever starts passing, validation has drifted back up
	 * into the principal-aware pass.
	 */
	it("denies a HUMAN editing a frozen document, with the gate carve-out untouched", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { grand_total: 999 } },
				TEST_ENV,
				ctxFor(org.id, { userId: user.id }),
			),
		).rejects.toThrow(/frozen/i);

		expect((await readMetadata(invoice.id)).grand_total).toBe(100);
	});

	it("denies an illegal transition and permits a legal one", async () => {
		const { org, user, invoice } = await seedInvoice("draft");
		const ctx = ctxFor(org.id, { userId: user.id });

		await expect(
			updateEntity(invoice.id, { metadata: { status: "posted" } }, TEST_ENV, ctx),
		).rejects.toThrow(/illegal transition/i);
		expect((await readMetadata(invoice.id)).status).toBe("draft");

		await updateEntity(
			invoice.id,
			{ metadata: { status: "issued" } },
			TEST_ENV,
			ctx,
		);
		expect((await readMetadata(invoice.id)).status).toBe("issued");
	});

	it("permits a writableOnExit field in the same write as its move", async () => {
		const { org, user, invoice } = await seedInvoice("issued");

		await updateEntity(
			invoice.id,
			{ metadata: { status: "posted", einvoice_uuid: "GIB-1" } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);

		const after = await readMetadata(invoice.id);
		expect(after.status).toBe("posted");
		expect(after.einvoice_uuid).toBe("GIB-1");
	});

	it("denies renaming a frozen document", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		await expect(
			updateEntity(invoice.id, { name: "Renamed" }, TEST_ENV, ctxFor(org.id, {
				userId: user.id,
			})),
		).rejects.toThrow(/frozen/i);
	});

	it("permits an idempotent rewrite of an unchanged value while frozen", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		await updateEntity(
			invoice.id,
			{ metadata: { grand_total: 100 } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);

		expect((await readMetadata(invoice.id)).grand_total).toBe(100);
	});

	it("fails closed when a type declares a malformed spec", async () => {
		const { org, user, invoice } = await seedInvoice("posted", {
			field: "status",
			states: "not-an-object",
		});

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { grand_total: 999 } },
				TEST_ENV,
				ctxFor(org.id, { userId: user.id }),
			),
		).rejects.toThrow(/invalid x-transitions/i);
	});

	it("leaves a type declaring no transitions untouched", async () => {
		const org = await createTestOrganization({ name: "No Spec" });
		const user = await createTestUser();
		await addUserToOrganization(user.id, org.id, "owner");
		const sql = getTestDb();
		await sql`
      INSERT INTO entity_types (organization_id, slug, name, created_at, updated_at)
      VALUES (${org.id}, 'note', 'note', current_timestamp, current_timestamp)
    `;
		const note = await createEntity({
			entity_type: "note",
			name: "Free-form",
			organization_id: org.id,
			created_by: user.id,
			metadata: { status: "posted", body: "x" },
		} as Parameters<typeof createEntity>[0]);

		await updateEntity(
			note.id,
			{ metadata: { body: "y" } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);
		expect((await readMetadata(note.id)).body).toBe("y");
	});

	/**
	 * Domain-neutrality check. The engine must know nothing about invoices; the
	 * cheapest way to keep that true is to run the identical path over a support
	 * ticket. If this ever needs its own branch in the rules module, domain
	 * vocabulary has leaked in.
	 */
	it("runs unchanged on a non-ERP lifecycle", async () => {
		const org = await createTestOrganization({ name: "Tickets" });
		const user = await createTestUser();
		await addUserToOrganization(user.id, org.id, "owner");
		await seedType(org.id, "ticket", {
			field: "state",
			states: {
				open: { to: ["triaged"] },
				triaged: { to: ["closed"] },
				closed: { to: [], frozen: true },
			},
		});
		const ticket = await createEntity({
			entity_type: "ticket",
			name: "TKT-1",
			organization_id: org.id,
			created_by: user.id,
			metadata: { state: "closed", title: "boom" },
		} as Parameters<typeof createEntity>[0]);

		await expect(
			updateEntity(
				ticket.id,
				{ metadata: { title: "edited" } },
				TEST_ENV,
				ctxFor(org.id, { userId: user.id }),
			),
		).rejects.toThrow(/frozen/i);
	});
});

