/**
 * SPIKE (redo): measure the REAL isolate, not a pg_sleep stand-in.
 *
 * The previous spike held the row lock with `pg_sleep`, which blocks a Postgres
 * backend while Node sits idle on the socket. A real rule blocks whatever thread
 * isolated-vm runs guest code on. If that is the main thread, the cost is
 * PER-PROCESS — every concurrent request stalls, not just writers to the same
 * row — and `pg_sleep` was structurally incapable of showing it.
 *
 * `run-script.ts:1145` runs guest code as
 *   script.run(context, { timeout, promise: true, copy: true })
 * so this mirrors that call exactly, along with the surrounding lifecycle
 * (`new ivm.Isolate` :903, `createContext` :904, `compileScript` :1141,
 * `dispose` :1271) — the same create-per-run shape that made it 4.5ms.
 *
 * Two questions:
 *   1. Does concurrency raise throughput? (off-thread) or is it flat? (on-thread)
 *   2. How far behind does a 1ms heartbeat fall while isolates run?
 *      Heartbeat lag IS event-loop starvation — it is what would delay every
 *      unrelated read, health check, and socket in the process.
 */

import ivm from "isolated-vm";
import { describe, it } from "vitest";

const CONCURRENCY = [1, 4, 16];
const OPS = 64;

/** A rule of realistic shape: a freeze check plus a cross-field sum. */
const RULE_SOURCE = `
	function rule(ctx) {
		const c = ctx.committed, p = ctx.patch;
		if (c.status === "posted") return "frozen";
		let sum = 0;
		for (const line of p.lines) sum += line.amount;
		if (sum !== p.header_net) return "lines do not sum to header";
		return null;
	}
	rule({
		committed: { status: "draft", header_net: 3 },
		patch: { header_net: 3, lines: [{ amount: 1 }, { amount: 2 }] },
	});
`;

async function oneIsolateRun(): Promise<void> {
	const isolate = new ivm.Isolate({ memoryLimit: 128 });
	try {
		const context = await isolate.createContext();
		const script = await isolate.compileScript(RULE_SOURCE);
		await script.run(context, {
			timeout: 1000,
			promise: true,
			copy: true,
		});
	} finally {
		isolate.dispose();
	}
}

/** Sample event-loop lag: how late a 1ms timer actually fires. */
function startHeartbeat() {
	const lags: number[] = [];
	let last = performance.now();
	const timer = setInterval(() => {
		const now = performance.now();
		lags.push(now - last - 1);
		last = now;
	}, 1);
	return {
		stop(): number[] {
			clearInterval(timer);
			return lags.sort((a, b) => a - b);
		},
	};
}

function pct(sorted: number[], p: number): number {
	if (sorted.length === 0) return 0;
	const i = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
	return sorted[i];
}

/** Run `total` isolate runs with at most `workers` in flight. */
async function runBatch(
	total: number,
	workers: number,
): Promise<{ wall: number; lat: number[] }> {
	const lat: number[] = [];
	let next = 0;
	const started = performance.now();
	await Promise.all(
		Array.from({ length: workers }, async () => {
			while (true) {
				const mine = next++;
				if (mine >= total) return;
				const t0 = performance.now();
				await oneIsolateRun();
				lat.push(performance.now() - t0);
			}
		}),
	);
	return { wall: performance.now() - started, lat: lat.sort((a, b) => a - b) };
}

describe("SPIKE: real isolate cost and event-loop impact", () => {
	it("measures throughput scaling and heartbeat starvation", async () => {
		await runBatch(8, 1); // warm up the addon and the plan caches

		const lines: string[] = [];
		lines.push("");
		lines.push("workers  ops  wall_ms  ops/s   p50_ms  p95_ms  | hb_p50  hb_p95  hb_max");
		lines.push("-------  ---  -------  ------  ------  ------  | ------  ------  ------");

		for (const workers of CONCURRENCY) {
			const hb = startHeartbeat();
			const { wall, lat } = await runBatch(OPS, workers);
			const lags = hb.stop();
			lines.push(
				[
					String(workers).padStart(7),
					String(lat.length).padStart(5),
					wall.toFixed(1).padStart(9),
					(lat.length / (wall / 1000)).toFixed(1).padStart(7),
					pct(lat, 50).toFixed(2).padStart(8),
					pct(lat, 95).toFixed(2).padStart(8),
					"  |",
					pct(lags, 50).toFixed(2).padStart(8),
					pct(lags, 95).toFixed(2).padStart(8),
					lags[lags.length - 1].toFixed(2).padStart(8),
				].join(""),
			);
		}

		// Baseline: heartbeat lag with NO isolate work at all, same duration.
		const idleHb = startHeartbeat();
		await new Promise((r) => setTimeout(r, 300));
		const idleLags = idleHb.stop();
		lines.push("");
		lines.push(
			`idle baseline heartbeat: p50 ${pct(idleLags, 50).toFixed(2)}ms  ` +
				`p95 ${pct(idleLags, 95).toFixed(2)}ms  ` +
				`max ${idleLags[idleLags.length - 1].toFixed(2)}ms`,
		);
		lines.push(`cpus: ${require("node:os").cpus().length}`);
		lines.push("");
		// biome-ignore lint/suspicious/noConsole: spike output is the deliverable
		console.log(lines.join("\n"));
	}, 300_000);
});

/**
 * Real-isolate benchmark: throughput scaling + event-loop starvation.
 * Mirrors run-script.ts's lifecycle and its exact run() options (:1145).
 */
import ivm from "isolated-vm";
import os from "node:os";

const CONCURRENCY = [1, 4, 16];
const OPS = 64;

const RULE_SOURCE = `
	function rule(ctx) {
		const c = ctx.committed, p = ctx.patch;
		if (c.status === "posted") return "frozen";
		let sum = 0;
		for (const line of p.lines) sum += line.amount;
		if (sum !== p.header_net) return "lines do not sum to header";
		return null;
	}
	rule({
		committed: { status: "draft", header_net: 3 },
		patch: { header_net: 3, lines: [{ amount: 1 }, { amount: 2 }] },
	});
`;

async function oneIsolateRun() {
  const isolate = new ivm.Isolate({ memoryLimit: 128 });
  try {
    const context = await isolate.createContext();
    const script = await isolate.compileScript(RULE_SOURCE);
    await script.run(context, { timeout: 1000, promise: true, copy: true });
  } finally {
    isolate.dispose();
  }
}

function startHeartbeat() {
  const lags = [];
  let last = performance.now();
  const timer = setInterval(() => {
    const now = performance.now();
    lags.push(now - last - 1);
    last = now;
  }, 1);
  return {
    stop() {
      clearInterval(timer);
      return lags.sort((a, b) => a - b);
    },
  };
}

function pct(sorted, p) {
  if (sorted.length === 0) return 0;
  const i = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
  return sorted[i];
}

async function runBatch(total, workers) {
  const lat = [];
  let next = 0;
  const started = performance.now();
  await Promise.all(
    Array.from({ length: workers }, async () => {
      while (true) {
        const mine = next++;
        if (mine >= total) return;
        const t0 = performance.now();
        await oneIsolateRun();
        lat.push(performance.now() - t0);
      }
    }),
  );
  return { wall: performance.now() - started, lat: lat.sort((a, b) => a - b) };
}

await runBatch(8, 1); // warm up

const out = [];
out.push("");
out.push("workers  ops  wall_ms  ops/s   p50_ms  p95_ms  | hb_p50  hb_p95  hb_max");
out.push("-------  ---  -------  ------  ------  ------  | ------  ------  ------");

for (const workers of CONCURRENCY) {
  const hb = startHeartbeat();
  const { wall, lat } = await runBatch(OPS, workers);
  const lags = hb.stop();
  out.push(
    [
      String(workers).padStart(7),
      String(lat.length).padStart(5),
      wall.toFixed(1).padStart(9),
      (lat.length / (wall / 1000)).toFixed(1).padStart(7),
      pct(lat, 50).toFixed(2).padStart(8),
      pct(lat, 95).toFixed(2).padStart(8),
      "  |",
      pct(lags, 50).toFixed(2).padStart(8),
      pct(lags, 95).toFixed(2).padStart(8),
      lags[lags.length - 1].toFixed(2).padStart(8),
    ].join(""),
  );
}

const idleHb = startHeartbeat();
await new Promise((r) => setTimeout(r, 300));
const idle = idleHb.stop();
out.push("");
out.push(
  `idle baseline heartbeat: p50 ${pct(idle, 50).toFixed(2)}ms  p95 ${pct(idle, 95).toFixed(2)}ms  max ${idle[idle.length - 1].toFixed(2)}ms`,
);
out.push(`cpus: ${os.cpus().length}   runtime: ${process.versions.bun ? `bun ${process.versions.bun}` : `node ${process.version}`}`);
out.push("");
console.log(out.join("\n"));

