import { defineConfig } from "@lobu/cli";
import { invoice } from "./entities/invoice";
import { customer } from "./entities/customer";
import { controller, importer } from "./agents/controller";

export default defineConfig({
  entities: [invoice, customer],
  agents: [controller, importer],

  // Queryable tier: compiled to write_approval_policies rows at apply time.
  // No row data involved, so it can answer "may I?" before anything is attempted.
  policy: {
    agents: {
      operations:  { "slack.send_message": "approval" },
      agentConfig: { delete: "deny" },
      entities:    { delete: "approval" },   // org-wide default across types
    },
  },
