			out.push(
				`  ${String(size).padStart(3)}  ${perRow.toFixed(1).padStart(8)}  ` +
					`${perBatch.toFixed(1).padStart(9)}  ${(perRow / perBatch).toFixed(1).padStart(7)}x  ` +
					`${(perBatch / size).toFixed(3).padStart(9)}`,
			);
		}

