/**
 * Entity row validation at the physical writer, driven by a type's compiled
 * write rules.
 *
 * These run the REAL path: an author's rule source is compiled exactly as the
 * apply path would store it, written to `entity_types.rules_compiled`, and then
 * exercised through `updateEntity` — not through the validator in isolation. A
 * rule that is never reached would pass a unit test of the evaluator and fail
 * here, which is the failure mode worth catching.
 */

import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import { compileEntityRule } from "../../../authz/entity-rule-executor";
import type { Env } from "../../../index";
import type { ToolContext } from "../../../tools/registry";
import { createEntity, updateEntity } from "../../../utils/entity-management";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	addUserToOrganization,
	createTestAgent,
	createTestOrganization,
	createTestUser,
} from "../../setup/test-fixtures";

/**
 * The invoice lifecycle as an author would write it.
 *
 * Note the two comparisons that look redundant and are not. `row.patch` carries
 * the fully MERGED metadata, not a delta, so every key of the object shows up on
 * every write. `from !== to` is what stops a rename from reading as an illegal
 * `issued -> issued`, and the JSON compare inside the frozen loop is what lets
 * an unchanged value ride along in a write that touches something else. A rule
 * that skipped either would deny writes it should permit.
 */
const INVOICE_RULE = `
const ALLOWED = { draft: ["issued"], issued: ["posted"], posted: [] };
const FROZEN = ["issued", "posted"];
const WRITABLE_ON_EXIT = { "issued->posted": ["einvoice_uuid"] };
const same = (a, b) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);

export default (row) => {
  if (row.op === "create") {
    if (row.next.status !== "draft") {
      row.deny("an invoice is created in draft, not " + row.next.status);
    }
    return;
  }

  const from = row.committed.status;
  const to = row.next.status;
  if (from !== to && !(ALLOWED[from] || []).includes(to)) {
    row.deny("cannot move " + from + " -> " + to);
  }

  if (!FROZEN.includes(from)) return;
  const permitted = ["status"].concat(WRITABLE_ON_EXIT[from + "->" + to] || []);
  for (const field of Object.keys(row.patch)) {
    if (permitted.includes(field)) continue;
    if (same(row.committed[field], row.patch[field])) continue;
    row.deny(from + " is frozen: " + field + " is not writable");
  }
};
`;

/** A lifecycle with nothing ERP about it, to prove the seam is type-scoped. */
const TICKET_RULE = `
export default (row) => {
  if (row.op === "update" && row.committed.state === "closed" && row.next.state === "open") {
    row.deny("a closed ticket cannot be reopened");
  }
};
`;

const TEST_ENV = {} as Env;

// esbuild costs ~100ms per call, so compile each rule once for the whole file.
let invoiceCompiled: string;
let ticketCompiled: string;

function ctxFor(
	organizationId: string,
	opts: { userId?: string | null; agentId?: string | null },
): ToolContext {
	return {
		organizationId,
		userId: opts.userId ?? null,
		memberRole: "owner",
		agentId: opts.agentId ?? null,
		isAuthenticated: true,
		clientId: null,
		scopes: ["mcp:read", "mcp:write", "mcp:admin"],
		tokenType: "oauth",
		scopedToOrg: true,
		allowCrossOrg: false,
	} as unknown as ToolContext;
}

async function seedType(
	organizationId: string,
	slug: string,
	rulesCompiled: string | null,
) {
	const sql = getTestDb();
	await sql`
    INSERT INTO entity_types (organization_id, slug, name, metadata_schema,
                              rules_compiled, created_at, updated_at)
    VALUES (${organizationId}, ${slug}, ${slug}, ${sql.json({ type: "object" })},
            ${rulesCompiled}, current_timestamp, current_timestamp)
  `;
}

async function readMetadata(id: number): Promise<Record<string, unknown>> {
	const sql = getTestDb();
	const rows = await sql<{ metadata: unknown }[]>`
    SELECT metadata FROM entities WHERE id = ${id}
  `;
	const raw = rows[0].metadata;
	return (typeof raw === "string" ? JSON.parse(raw) : raw) as Record<
		string,
		unknown
	>;
}

async function seedOrg(name: string) {
	const org = await createTestOrganization({ name });
	const user = await createTestUser();
	await addUserToOrganization(user.id, org.id, "owner");
	const agent = await createTestAgent({ organizationId: org.id });
	return { org, user, agent };
}

/**
 * Seed an invoice and walk it to `status` through legal transitions only.
 * Creates are validated now, so a fixture cannot be born mid-lifecycle — it has
 * to get there the way a tenant would.
 */
async function seedInvoice(
	status: "draft" | "issued" | "posted",
	rule: string | null = invoiceCompiled,
) {
	const { org, user, agent } = await seedOrg(`Invoice ${status}`);
	await seedType(org.id, "invoice", rule);

	const invoice = await createEntity({
		entity_type: "invoice",
		name: "INV-1",
		organization_id: org.id,
		created_by: user.id,
		metadata: { status: "draft", einvoice_uuid: null, amount: 100 },
	} as Parameters<typeof createEntity>[0]);

	const ctx = ctxFor(org.id, { userId: user.id });
	if (status === "issued" || status === "posted") {
		await updateEntity(
			invoice.id,
			{ metadata: { status: "issued" } },
			TEST_ENV,
			ctx,
		);
	}
	if (status === "posted") {
		await updateEntity(
			invoice.id,
			{ metadata: { status: "posted", einvoice_uuid: "uuid-seed" } },
			TEST_ENV,
			ctx,
		);
	}
	return { org, user, agent, invoice };
}

describe("entity row validation at the physical writer", () => {
	beforeAll(async () => {
		[invoiceCompiled, ticketCompiled] = await Promise.all([
			compileEntityRule(INVOICE_RULE),
			compileEntityRule(TICKET_RULE),
		]);
	}, 60_000);

	beforeEach(async () => {
		await cleanupTestDatabase();
	});

	it("denies an AGENT editing a frozen document", async () => {
		const { org, agent, invoice } = await seedInvoice("posted");

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { amount: 999 } },
				TEST_ENV,
				ctxFor(org.id, { agentId: agent.agentId }),
			),
		).rejects.toThrow(/posted is frozen: amount/);

		expect((await readMetadata(invoice.id)).amount).toBe(100);
	}, 60_000);

	it("denies a HUMAN editing a frozen document — validation has no principal in it", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		// The permission gate carves out humans. This seam answers a different
		// question ("is the resulting state legal"), so an owner is denied too.
		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { amount: 999 } },
				TEST_ENV,
				ctxFor(org.id, { userId: user.id }),
			),
		).rejects.toThrow(/posted is frozen: amount/);
	}, 60_000);

	it("denies an illegal transition and permits a legal one", async () => {
		const { org, user, invoice } = await seedInvoice("draft");
		const ctx = ctxFor(org.id, { userId: user.id });

		await expect(
			updateEntity(invoice.id, { metadata: { status: "posted" } }, TEST_ENV, ctx),
		).rejects.toThrow(/cannot move draft -> posted/);
		expect((await readMetadata(invoice.id)).status).toBe("draft");

		await updateEntity(
			invoice.id,
			{ metadata: { status: "issued" } },
			TEST_ENV,
			ctx,
		);
		expect((await readMetadata(invoice.id)).status).toBe("issued");
	}, 60_000);

	it("permits a writableOnExit field in the same write as its move", async () => {
		const { org, user, invoice } = await seedInvoice("issued");

		await updateEntity(
			invoice.id,
			{ metadata: { status: "posted", einvoice_uuid: "uuid-xyz" } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);

		const after = await readMetadata(invoice.id);
		expect(after.status).toBe("posted");
		expect(after.einvoice_uuid).toBe("uuid-xyz");
	}, 60_000);

	it("denies renaming a frozen document", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		// Freezing a document has to stop a rename, not merely a metadata edit —
		// which is why `$name` is a governed column rather than an ungoverned one.
		await expect(
			updateEntity(invoice.id, { name: "INV-RENAMED" }, TEST_ENV, ctxFor(org.id, {
				userId: user.id,
			})),
		).rejects.toThrow(/posted is frozen: \$name/);
	}, 60_000);

	it("permits an idempotent rewrite of an unchanged value while frozen", async () => {
		const { org, user, invoice } = await seedInvoice("posted");

		// The merged patch carries every metadata key on every write, so a rule
		// that denied on presence rather than on change would reject this.
		await updateEntity(
			invoice.id,
			{ metadata: { amount: 100 } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);

		expect((await readMetadata(invoice.id)).amount).toBe(100);
	}, 60_000);

	it("leaves a type declaring no rules untouched", async () => {
		const { org, user, invoice } = await seedInvoice("draft", null);

		// No rule means no isolate — the write that the invoice rule would have
		// rejected outright goes straight through.
		await updateEntity(
			invoice.id,
			{ metadata: { status: "posted" } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);

		expect((await readMetadata(invoice.id)).status).toBe("posted");
	}, 60_000);

	it("scopes rules to their own type", async () => {
		const { org, user } = await seedOrg("Mixed types");
		await seedType(org.id, "invoice", invoiceCompiled);
		await seedType(org.id, "ticket", ticketCompiled);
		const ctx = ctxFor(org.id, { userId: user.id });

		const ticket = await createEntity({
			entity_type: "ticket",
			name: "TCK-1",
			organization_id: org.id,
			created_by: user.id,
			metadata: { state: "open" },
		} as Parameters<typeof createEntity>[0]);

		// The invoice rule would have denied a create whose status is not "draft".
		// The ticket has no `status` at all and its own rule permits the create.
		await updateEntity(ticket.id, { metadata: { state: "closed" } }, TEST_ENV, ctx);
		expect((await readMetadata(ticket.id)).state).toBe("closed");

		await expect(
			updateEntity(ticket.id, { metadata: { state: "open" } }, TEST_ENV, ctx),
		).rejects.toThrow(/closed ticket cannot be reopened/);
	}, 60_000);
});

/**
 * Creates reach the validation seam.
 *
 * This file began as a spike proving the opposite. `insertEntityRow` never
 * called the validator, so every state rule was trivially routable: an agent
 * denied a `draft -> posted` update simply created the document already posted,
 * and "posting requires an e-invoice UUID" only ever bit someone who took a
 * legal draft and edited it — i.e. someone already following the rules.
 *
 * The fix was the same brand the update path already carried, applied to the
 * second writer, so a caller that forgets to validate a create fails to compile.
 * The cases below are the regression test for that: the first two assert the
 * creates are now DENIED, and the third is the contrast that pins the rule as
 * the cause rather than some unrelated error.
 */

import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import { compileEntityRule } from "../../../authz/entity-rule-executor";
import type { Env } from "../../../index";
import type { ToolContext } from "../../../tools/registry";
import { createEntity, updateEntity } from "../../../utils/entity-management";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	addUserToOrganization,
	createTestAgent,
	createTestOrganization,
	createTestUser,
} from "../../setup/test-fixtures";

/**
 * `posted` is terminal and frozen. Reaching it legally means passing through
 * `issued`, and `einvoice_uuid` is only writable on the exit INTO `posted`.
 *
 * The `op === "create"` branch is the whole point: a create is an update from
 * nothing, so `committed` is empty and the rule decides what a row is allowed to
 * be born as. Without that branch the transition table below governs edits only.
 */
const INVOICE_RULE = `
const ALLOWED = { draft: ["issued"], issued: ["posted"], posted: [] };

export default (row) => {
  if (row.op === "create") {
    if (row.next.status !== "draft") {
      row.deny("an invoice is created in draft, not " + row.next.status);
    }
    return;
  }
  const from = row.committed.status;
  const to = row.next.status;
  if (from !== to && !(ALLOWED[from] || []).includes(to)) {
    row.deny("cannot move " + from + " -> " + to);
  }
  if (to === "posted" && !row.next.einvoice_uuid) {
    row.deny("posting requires an e-invoice UUID");
  }
};
`;

const TEST_ENV = {} as Env;
let invoiceCompiled: string;

function ctxFor(
	organizationId: string,
	opts: { userId?: string | null; agentId?: string | null },
): ToolContext {
	return {
		organizationId,
		userId: opts.userId ?? null,
		memberRole: "owner",
		agentId: opts.agentId ?? null,
		isAuthenticated: true,
		clientId: null,
		scopes: ["mcp:read", "mcp:write", "mcp:admin"],
		tokenType: "oauth",
		scopedToOrg: true,
		allowCrossOrg: false,
	} as unknown as ToolContext;
}

async function seedOrg() {
	const sql = getTestDb();
	const org = await createTestOrganization({ name: "Create Validation" });
	const user = await createTestUser();
	await addUserToOrganization(user.id, org.id, "owner");
	const agent = await createTestAgent({ organizationId: org.id });
	await sql`
    INSERT INTO entity_types (organization_id, slug, name, metadata_schema,
                              rules_compiled, created_at, updated_at)
    VALUES (${org.id}, 'invoice', 'invoice', ${sql.json({ type: "object" })},
            ${invoiceCompiled}, current_timestamp, current_timestamp)
  `;
	return { org, user, agent };
}

async function statusOf(id: number): Promise<unknown> {
	const sql = getTestDb();
	const rows = await sql<{ metadata: unknown }[]>`
    SELECT metadata FROM entities WHERE id = ${id}`;
	const raw = rows[0].metadata;
	const md = (typeof raw === "string" ? JSON.parse(raw) : raw) as Record<
		string,
		unknown
	>;
	return md.status;
}

async function countInvoices(organizationId: string): Promise<number> {
	const sql = getTestDb();
	const rows = await sql<{ n: string }[]>`
    SELECT count(*)::text AS n FROM entities WHERE organization_id = ${organizationId}
  `;
	return Number(rows[0].n);
}

describe("creates reach the validation seam", () => {
	beforeAll(async () => {
		invoiceCompiled = await compileEntityRule(INVOICE_RULE);
	}, 60_000);

	beforeEach(async () => {
		await cleanupTestDatabase();
	});

	it("denies an invoice born DIRECTLY in the terminal frozen state", async () => {
		const { org, user } = await seedOrg();

		await expect(
			createEntity({
				entity_type: "invoice",
				name: "INV-BORN-POSTED",
				organization_id: org.id,
				created_by: user.id,
				metadata: { status: "posted", einvoice_uuid: "uuid-1" },
			} as Parameters<typeof createEntity>[0]),
		).rejects.toThrow(/an invoice is created in draft, not posted/);

		// The whole insert rolled back — no half-created row behind the denial.
		expect(await countInvoices(org.id)).toBe(0);
	}, 60_000);

	it("denies a POSTED invoice with no e-invoice UUID", async () => {
		const { org, user } = await seedOrg();

		await expect(
			createEntity({
				entity_type: "invoice",
				name: "INV-POSTED-NO-UUID",
				organization_id: org.id,
				created_by: user.id,
				metadata: { status: "posted" },
			} as Parameters<typeof createEntity>[0]),
		).rejects.toThrow(/an invoice is created in draft, not posted/);

		expect(await countInvoices(org.id)).toBe(0);
	}, 60_000);

	it("permits the legal create and still denies the same end state by update", async () => {
		const { org, user, agent } = await seedOrg();

		const invoice = await createEntity({
			entity_type: "invoice",
			name: "INV-LEGAL-DRAFT",
			organization_id: org.id,
			created_by: user.id,
			metadata: { status: "draft", einvoice_uuid: null },
		} as Parameters<typeof createEntity>[0]);
		expect(await statusOf(invoice.id)).toBe("draft");

		await expect(
			updateEntity(
				invoice.id,
				{ metadata: { status: "posted", einvoice_uuid: "uuid-1" } },
				TEST_ENV,
				ctxFor(org.id, { userId: user.id, agentId: agent.agentId }),
			),
		).rejects.toThrow(/cannot move draft -> posted/);

		// And the row is untouched — the deny rolled the write back.
		expect(await statusOf(invoice.id)).toBe("draft");
	}, 60_000);
});

/**
 * KNOWN BUG: an approval hold on the state field turns a LEGAL transition into
 * a frozen-state violation, losing both the write and the approval card.
 *
 * Sequence under test:
 *   1. invoice sits in `draft`
 *   2. a HUMAN moves it to `issued` — legal, and claims ownership of `status`
 *   3. an AGENT proposes the legal exit `issued -> posted` together with
 *      `einvoice_uuid`, the one field that move unlocks
 *   4. the permission gate holds `status` (human-owned), so `computeFieldMerge`
 *      strips it from the patch
 *   5. the effective patch is `{ einvoice_uuid }` with NO transition — and in a
 *      frozen state that is illegal, so the rule denies the whole write
 *
 * The agent proposed something legal. An unrelated ownership hold made it
 * illegal. And `entity-management.ts` builds the approval deferral AFTER the
 * transaction returns, so the throw means no card is queued either. The work is
 * denied, misattributed to the rule, and dropped.
 *
 * This must be fixed BEFORE write rules are armed for tenants: arming them turns
 * a latent ordering bug into a routine way to lose an agent's work. The control
 * test proves the hold is the cause — the identical agent write succeeds when no
 * human owns `status`.
 */

import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import { compileEntityRule } from "../../../authz/entity-rule-executor";
import type { Env } from "../../../index";
import type { ToolContext } from "../../../tools/registry";
import { createEntity, updateEntity } from "../../../utils/entity-management";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	addUserToOrganization,
	createTestAgent,
	createTestOrganization,
	createTestUser,
} from "../../setup/test-fixtures";

const INVOICE_RULE = `
const ALLOWED = { draft: ["issued"], issued: ["posted"], posted: [] };
const FROZEN = ["issued", "posted"];
const WRITABLE_ON_EXIT = { "issued->posted": ["einvoice_uuid"] };
const same = (a, b) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);

export default (row) => {
  if (row.op === "create") {
    if (row.next.status !== "draft") {
      row.deny("an invoice is created in draft, not " + row.next.status);
    }
    return;
  }
  const from = row.committed.status;
  const to = row.next.status;
  if (from !== to && !(ALLOWED[from] || []).includes(to)) {
    row.deny("cannot move " + from + " -> " + to);
  }
  if (!FROZEN.includes(from)) return;
  const permitted = ["status"].concat(WRITABLE_ON_EXIT[from + "->" + to] || []);
  for (const field of Object.keys(row.patch)) {
    if (permitted.includes(field)) continue;
    if (same(row.committed[field], row.patch[field])) continue;
    row.deny(from + " is frozen: " + field + " is not writable");
  }
};
`;

const TEST_ENV = {} as Env;
let invoiceCompiled: string;

function ctxFor(
	organizationId: string,
	opts: { userId?: string | null; agentId?: string | null },
): ToolContext {
	return {
		organizationId,
		userId: opts.userId ?? null,
		memberRole: "owner",
		agentId: opts.agentId ?? null,
		isAuthenticated: true,
		clientId: null,
		scopes: ["mcp:read", "mcp:write", "mcp:admin"],
		tokenType: "oauth",
		scopedToOrg: true,
		allowCrossOrg: false,
	} as unknown as ToolContext;
}

async function readMetadata(id: number): Promise<Record<string, unknown>> {
	const sql = getTestDb();
	const rows = await sql<{ metadata: unknown }[]>`
    SELECT metadata FROM entities WHERE id = ${id}
  `;
	const raw = rows[0].metadata;
	return (typeof raw === "string" ? JSON.parse(raw) : raw) as Record<
		string,
		unknown
	>;
}

async function runCount(organizationId: string): Promise<number> {
	const sql = getTestDb();
	const rows = await sql<{ n: string }[]>`
    SELECT count(*)::text AS n FROM runs WHERE organization_id = ${organizationId}
  `;
	return Number(rows[0].n);
}

async function seed() {
	const sql = getTestDb();
	const org = await createTestOrganization({ name: "Approval Hold" });
	const user = await createTestUser();
	await addUserToOrganization(user.id, org.id, "owner");
	const agent = await createTestAgent({ organizationId: org.id });
	await sql`
    INSERT INTO entity_types (organization_id, slug, name, metadata_schema,
                              rules_compiled, created_at, updated_at)
    VALUES (${org.id}, 'invoice', 'invoice', ${sql.json({ type: "object" })},
            ${invoiceCompiled}, current_timestamp, current_timestamp)
  `;
	const invoice = await createEntity({
		entity_type: "invoice",
		name: "INV-HOLD",
		organization_id: org.id,
		created_by: user.id,
		metadata: { status: "draft", einvoice_uuid: null },
	} as Parameters<typeof createEntity>[0]);
	return { org, user, agent, invoice };
}

describe("approval hold vs a frozen-state rule", () => {
	beforeAll(async () => {
		invoiceCompiled = await compileEntityRule(INVOICE_RULE);
	}, 60_000);

	beforeEach(async () => {
		await cleanupTestDatabase();
	});

	it("CONTROL: the agent's legal exit succeeds when no human owns `status`", async () => {
		const { org, agent, invoice } = await seed();
		const agentCtx = ctxFor(org.id, { agentId: agent.agentId });

		// An AGENT moves draft -> issued, so no human ownership is claimed.
		await updateEntity(
			invoice.id,
			{ metadata: { status: "issued" } },
			TEST_ENV,
			agentCtx,
		);
		expect((await readMetadata(invoice.id)).status).toBe("issued");

		// The legal exit, carrying the field that move unlocks.
		await updateEntity(
			invoice.id,
			{ metadata: { status: "posted", einvoice_uuid: "uuid-xyz" } },
			TEST_ENV,
			agentCtx,
		);

		const after = await readMetadata(invoice.id);
		expect(after.status).toBe("posted");
		expect(after.einvoice_uuid).toBe("uuid-xyz");
	}, 60_000);

	it("BUG: the identical write is denied once a human owns `status`", async () => {
		const { org, user, agent, invoice } = await seed();

		// A HUMAN moves draft -> issued. Legal, and it claims ownership of `status`.
		await updateEntity(
			invoice.id,
			{ metadata: { status: "issued" } },
			TEST_ENV,
			ctxFor(org.id, { userId: user.id }),
		);
		expect((await readMetadata(invoice.id)).status).toBe("issued");

		const runsBefore = await runCount(org.id);

		// The SAME legal exit the control test just performed successfully.
		const attempt = updateEntity(
			invoice.id,
			{ metadata: { status: "posted", einvoice_uuid: "uuid-xyz" } },
			TEST_ENV,
			ctxFor(org.id, { agentId: agent.agentId }),
		);

		// Misattributed: the rule reports a frozen-field violation, because the
		// transition it would have permitted was stripped before it ever ran.
		await expect(attempt).rejects.toThrow(
			/issued is frozen: einvoice_uuid is not writable/,
		);

		// Nothing landed: not the transition, not the permitted companion field.
		const after = await readMetadata(invoice.id);
		expect(after.status).toBe("issued");
		expect(after.einvoice_uuid ?? null).toBeNull();

		// And no approval card was queued, because the deferral is built after the
		// transaction returns and the throw skipped it.
		expect(await runCount(org.id)).toBe(runsBefore);
	}, 60_000);
});

